function drawEdge(x1, y1, x2, y2, drawDotted = false) {
	if (drawDotted) {
		drawDashedLine(x1, y1, x2, y2, 3);
	} else {	
		line(x1, y1, x2, y2);
	}
	return `<line x1="${nf(x1,0,1)}" y1="${nf(y1,0,1)}" x2="${nf(x2,0,1)}" y2="${nf(y2,0,1)}" />\n`;
}
function drawDashedLine(x1, y1, x2, y2, d = 3) {
  let dst = dist(x1, y1, x2, y2);

  // to small for dashed line
  if (dst <= d) {
    line(x1, y1, x2, y2);
    return;
  }

  // calc number of segments. 
  let n = round(dst / d);
  if (n % 2 === 0) n++; // force to nearest odd

  let segLen = dst / n;
  for (let i = 0; i < n; i++) {
    if (i % 2 === 0) { // skip empty segments
      let t1 = i / n;
      let t2 = (i + 1) / n;

      let sx = lerp(x1, x2, t1);
      let sy = lerp(y1, y2, t1);
      let ex = lerp(x1, x2, t2);
      let ey = lerp(y1, y2, t2);

      line(sx, sy, ex, ey);
    }
  }
}

