class Matrices {
  static multVec(m_in, v, debug = false) {
    if (m_in[0].length != v.length) {
      console.error(
        `Matrices.multVec: m_in[0].length ${m_in[0].length} != v.length ${v.length}`
      );
      return;
    }

    let m_out = [];
    for (let m_in_idx = 0; m_in_idx < m_in.length; m_in_idx++) {
      let sum = 0;
      for (let v_idx = 0; v_idx < v.length; v_idx++) {
        sum += m_in[m_in_idx][v_idx] * v[v_idx];
      }
      m_out[m_in_idx] = sum;
    }

    return m_out;
  }

  static multMatr(m1, m2) {
    if (m1[0].length != m2.length) {
      console.error(
        `Matrices.multVec: m1[0].length ${m1[0].length} != m2.length ${m2.length}`
      );
      return;
    }

    let m_out = [];
    for (let m1_idx = 0; m1_idx < m1.length; m1_idx++) {
      m_out[m1_idx] = Array(m2[0].length);

      for (let m2_col_idx = 0; m2_col_idx < m2[0].length; m2_col_idx++) {
        let sum = 0;
        for (let m2_row_idx = 0; m2_row_idx < m2.length; m2_row_idx++) {
          sum += m1[m1_idx][m2_row_idx] * m2[m2_row_idx][m2_col_idx];
        }
        m_out[m1_idx][m2_col_idx] = sum;
      }
    }

    return m_out;
  }
}


function camPrj(cam, pts) {
	const F = 0-cam[2]; // F=Z-Zc
	const prj = [];
	for (let p of pts) {
		const px = p[0];
		const py = p[1]
		const pz = p[2] ? p[2] : 0.0001;

		const x = ((p[0] - cam[0]) * (F/pz)) + cam[0]
		const y = ((p[1] - cam[1]) * (F/pz)) + cam[1]
		prj.push([x, y]);
	}
	return prj; // projected
}

